import Mathlib
def tokenCost (k v : ℕ) : ℕ := k + (k - 1) + k*v + (v - 1)
def Claim : Prop := ∃ c C : ℕ, 0 < c ∧ ∀ k v : ℕ, 1 ≤ k → 1 ≤ v → c*(k*v) ≤ tokenCost k v ∧ tokenCost k v ≤ C*(k*v)

import Mathlib
def sequenceCost (n k v : ℕ) : ℕ := n*(k + (k-1) + k*v + (v-1))
def Claim : Prop := ∃ c C : ℕ, 0 < c ∧ ∀ n k v : ℕ, 1 ≤ n → 1 ≤ k → 1 ≤ v → c*(n*k*v) ≤ sequenceCost n k v ∧ sequenceCost n k v ≤ C*(n*k*v)

import Mathlib
def correctStrings (L D : ℕ) (enc : (Fin L → Fin D) → Fin 16) (dec : Fin 16 → (Fin L → Fin D)) : ℕ := Fintype.card {x : Fin L → Fin D // dec (enc x) = x}
def Claim : Prop := ∀ L D : ℕ, 1 ≤ D → ∀ (enc : (Fin L → Fin D) → Fin 16) (dec : Fin 16 → (Fin L → Fin D)), correctStrings L D enc dec ≤ 16 ∧ ((∀ x, dec (enc x) = x) → D^L ≤ 16) ∧ (∀ l : ℕ, 8 ≤ l → l ≤ 64 → ∀ (e : (Fin l → Fin 4) → Fin 16) (d : Fin 16 → (Fin l → Fin 4)), (correctStrings l 4 e d : ℚ) / (4^l : ℚ) ≤ 16 / (4^l : ℚ) ∧ (correctStrings l 4 e d : ℚ) / (4^l : ℚ) < 99/100)

import Mathlib
def recallCorrect (K V : ℕ) (enc : (Fin K → Fin V) → Fin 16) (dec : Fin 16 → Fin K → Fin V) : ℕ := Fintype.card {p : (Fin K → Fin V) × Fin K // dec (enc p.1) p.2 = p.1 p.2}
def Claim : Prop := (∀ K V : ℕ, 1 ≤ V → ∀ (enc : (Fin K → Fin V) → Fin 16) (dec : Fin 16 → Fin K → Fin V), (∀ x i, dec (enc x) i = x i) → V^K ≤ 16) ∧ (∀ K : ℕ, 8 ≤ K → K ≤ 64 → ∀ (enc : (Fin K → Fin 16) → Fin 16) (dec : Fin 16 → Fin K → Fin 16), (recallCorrect K 16 enc dec : ℚ) / ((16^K * K : ℕ) : ℚ) < 99/100) ∧ (∀ (enc : (Fin 64 → Fin 16) → Fin 16) (dec : Fin 16 → Fin 64 → Fin 16), (recallCorrect 64 16 enc dec : ℚ) / ((16^64 * 64 : ℕ) : ℚ) ≤ 1/16)

import Mathlib
def successes (enc : (Fin 3 → Fin 4) → Fin 16) (dec : Fin 16 → (Fin 3 → Fin 4)) : ℕ := Fintype.card {x : Fin 3 → Fin 4 // dec (enc x) = x}
def Claim : Prop := (∀ (enc : (Fin 3 → Fin 4) → Fin 16) (dec : Fin 16 → (Fin 3 → Fin 4)), successes enc dec ≤ 16 ∧ (successes enc dec : ℚ)/64 < 99/100) ∧ (∀ L : ℕ, L < 3 → ∃ (enc : (Fin L → Fin 4) → Fin 16) (dec : Fin 16 → (Fin L → Fin 4)), ∀ x, dec (enc x) = x)

